import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Princípio de Apenas Retorno de Conhecimento","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0087-仅回传知识原则.md","filePath":"pt/0087-仅回传知识原则.md"}'),t={name:"pt/0087-仅回传知识原则.md"};function s(n,o,d,c,m,l){return a(),i("div",null,[...o[0]||(o[0]=[r('<h1 id="principio-de-apenas-retorno-de-conhecimento" tabindex="-1">Princípio de Apenas Retorno de Conhecimento <a class="header-anchor" href="#principio-de-apenas-retorno-de-conhecimento" aria-label="Permalink to &quot;Princípio de Apenas Retorno de Conhecimento&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>87</td></tr><tr><td>Módulo</td><td>Interação interplanar e regras temporais</td></tr><tr><td>Palavras-chave Principais</td><td>Apenas retorno de conhecimento, purificação de informação, proibição de retorno de matéria, codificação de conhecimento, auditoria de retorno</td></tr></tbody></table><h2 id="i-contexto-legislativo-e-ideia-central-do-principio" tabindex="-1">I. Contexto Legislativo e Ideia Central do Princípio <a class="header-anchor" href="#i-contexto-legislativo-e-ideia-central-do-principio" aria-label="Permalink to &quot;I. Contexto Legislativo e Ideia Central do Princípio&quot;">​</a></h2><p>O princípio de &quot;apenas retorno de conhecimento&quot; é um dos princípios fundamentais da arqueologia interplanar e de retrocesso temporal da civilização de simbiose de âncora, cuja origem legal remonta ao Artigo 48 da &quot;Constituição de Simbiose&quot;: &quot;Qualquer matéria, energia e ser vivo obtidos de outros planos ou outros períodos de tempo não podem ser trazidos para o próprio plano sem permissão especial; a produção legítima das atividades arqueológicas limita-se a conhecimento e informação abstratos.&quot; O estabelecimento deste princípio foi uma escolha institucional feita por Hengyuanzhou após resumir as lições dolorosas da exploração interplanar inicial.</p><p>No início do estabelecimento da civilização de simbiose de âncora, a exploração interplanar ainda estava em um estado desordenado. Alguns exploradores trouxeram amostras de matéria, cristais de energia e até mesmo seres vivos de outros planos para o próprio plano para pesquisa, causando vários graves &quot;incidentes de poluição interplanar&quot;. O caso mais famoso é o &quot;Incidente do Cristal Estranho&quot; — um cristal de energia trazido de um plano de manifestação de energia, devido à incompatibilidade de seus parâmetros legais com o próprio plano, causou uma desordem jurídica que durou três anos na rede de leis do próprio plano, resultando em anomalias no sistema de cultivo de três regiões estelares e dezenas de milhares de cultivadores sofrendo danos em vários graus. Investigações posteriores mostraram que, se o princípio de &quot;apenas retorno de conhecimento&quot; tivesse sido seguido na época, esse desastre poderia ter sido completamente evitado.</p><p>A ideia central do princípio de &quot;apenas retorno de conhecimento&quot; é: o conhecimento é o único meio seguro no intercâmbio entre civilizações. A matéria e a energia carregam as informações legais do plano de origem e podem causar reações imprevisíveis após entrar em ambientes legais diferentes; enquanto o conhecimento, como informação abstrata, após codificação e purificação adequadas, pode separar as impressões legais do plano de origem e se tornar um recurso seguro compartilhado entre planos.</p><h2 id="ii-definicao-e-classificacao-de-conhecimento" tabindex="-1">II. Definição e Classificação de &quot;Conhecimento&quot; <a class="header-anchor" href="#ii-definicao-e-classificacao-de-conhecimento" aria-label="Permalink to &quot;II. Definição e Classificação de &quot;Conhecimento&quot;&quot;">​</a></h2><p>No quadro jurídico do princípio de &quot;apenas retorno de conhecimento&quot;, o &quot;conhecimento&quot; tem definição e classificação rigorosas. Nem toda informação pode ser considerada &quot;conhecimento&quot; e retornada livremente — apenas a informação abstrata que passou pelo processo de &quot;purificação de informação&quot; e foi confirmada como não carregando qualquer poluição legal atende ao padrão de retorno.</p><p>O conhecimento é dividido em três categorias de acordo com seu grau de abstração e nível de segurança:</p><table tabindex="0"><thead><tr><th>Categoria de Conhecimento</th><th>Definição</th><th>Nível de Segurança</th><th>Requisito de Retorno</th></tr></thead><tbody><tr><td>Conhecimento de Nível 1 (Conhecimento Puramente Abstrato)</td><td>Conceitos abstratos completamente separados de portadores materiais, teoremas matemáticos, deduções lógicas, pensamentos filosóficos, etc.</td><td>Mais alto (verde)</td><td>Pode ser retornado diretamente, sem aprovação especial</td></tr><tr><td>Conhecimento de Nível 2 (Conhecimento Descritivo)</td><td>Informações descritivas de coisas objetivas, incluindo registros históricos, dados geográficos, características biológicas, descrições culturais, etc.</td><td>Médio (amarelo)</td><td>Deve passar por processo de purificação de informação, retornado após aprovação da Agência de Administração Planar</td></tr><tr><td>Conhecimento de Nível 3 (Conhecimento Técnico)</td><td>Conhecimento prático contendo parâmetros técnicos específicos, esquemas de engenharia, métodos de cultivo</td><td>Mais baixo (laranja)</td><td>Deve passar por purificação de informação rigorosa e avaliação de segurança, retornado após aprovação especial do Conselho de Âncoras</td></tr></tbody></table><p>Os seguintes conteúdos não pertencem à categoria de &quot;conhecimento&quot; e são estritamente proibidos de serem retornados: amostras de matéria de qualquer forma (incluindo microrganismos, células, fragmentos de genes), cristais de energia ou dispositivos de armazenamento de energia de qualquer forma, qualquer ser vivo ou corpo de consciência com consciência autônoma, quaisquer dados originais que não passaram por purificação de informação, e quaisquer detalhes técnicos que possam ser usados para cultivo predatório.</p><h2 id="iii-tecnologia-de-purificacao-de-informacao" tabindex="-1">III. Tecnologia de Purificação de Informação <a class="header-anchor" href="#iii-tecnologia-de-purificacao-de-informacao" aria-label="Permalink to &quot;III. Tecnologia de Purificação de Informação&quot;">​</a></h2><p>A purificação de informação é o elo técnico chave para garantir a segurança do conhecimento retornado. Seu objetivo central é separar completamente as impressões legais do plano de origem carregadas na informação original, mantendo apenas o conteúdo semântico puro. O processo de purificação de informação é dividido em quatro etapas:</p><h3 id="_3-1-desconstrucao-da-informacao" tabindex="-1">3.1 Desconstrução da Informação <a class="header-anchor" href="#_3-1-desconstrucao-da-informacao" aria-label="Permalink to &quot;3.1 Desconstrução da Informação&quot;">​</a></h3><p>Primeiro, a informação original a ser retornada é desconstruída estruturalmente, dividida em duas partes: &quot;conteúdo semântico&quot; e &quot;impressão do portador&quot;. O conteúdo semântico é o significado abstrato que a informação pretende expressar, e a impressão do portador são os parâmetros legais do plano de origem absorvidos pela informação durante o processo de armazenamento e transmissão. A desconstrução da informação é realizada através do &quot;algoritmo de separação semântica-portador&quot;, que pode identificar e separar os componentes semânticos e legais na informação.</p><h3 id="_3-2-separacao-legal" tabindex="-1">3.2 Separação Legal <a class="header-anchor" href="#_3-2-separacao-legal" aria-label="Permalink to &quot;3.2 Separação Legal&quot;">​</a></h3><p>É realizada uma separação legal completa na impressão do portador separada. O método de separação é passar a informação através do &quot;canal de neutralidade legal&quot; — este é um canal de transmissão especial cujos parâmetros legais são definidos como completamente neutros; quando a informação passa por ele, todos os parâmetros legais não neutros que carrega são absorvidos pelas paredes do canal. Após a separação legal, a informação não carrega mais nenhuma impressão legal do plano de origem.</p><h3 id="_3-3-reconstrucao-semantica" tabindex="-1">3.3 Reconstrução Semântica <a class="header-anchor" href="#_3-3-reconstrucao-semantica" aria-label="Permalink to &quot;3.3 Reconstrução Semântica&quot;">​</a></h3><p>Com base na separação legal, o conteúdo semântico é recodificado, e a informação é reconstruída usando o sistema padrão de codificação de informação do próprio plano. A reconstrução semântica garante que o conhecimento retornado possa ser lido e compreendido corretamente no ambiente legal do próprio plano, ao mesmo tempo que elimina ainda mais qualquer estrutura de informação do plano de origem que possa permanecer.</p><h3 id="_3-4-deteccao-de-seguranca" tabindex="-1">3.4 Detecção de Segurança <a class="header-anchor" href="#_3-4-deteccao-de-seguranca" aria-label="Permalink to &quot;3.4 Detecção de Segurança&quot;">​</a></h3><p>A informação purificada deve passar por detecção de segurança rigorosa, incluindo: detecção de resíduos legais (confirmar que a informação não carrega nenhum parâmetro legal estranho), detecção de integridade semântica (confirmar que o processo de purificação não alterou o conteúdo semântico da informação), e avaliação de risco potencial (avaliar o impacto social e de segurança que a disseminação deste conhecimento no próprio plano pode trazer). Apenas a informação que passa nas três detecções é permitida a ser retornada.</p><h2 id="iv-processo-de-retorno-e-sistema-de-auditoria" tabindex="-1">IV. Processo de Retorno e Sistema de Auditoria <a class="header-anchor" href="#iv-processo-de-retorno-e-sistema-de-auditoria" aria-label="Permalink to &quot;IV. Processo de Retorno e Sistema de Auditoria&quot;">​</a></h2><p>O retorno de conhecimento segue uma gestão de processo rigorosa. Uma operação de retorno completa inclui os seguintes elos:</p><ol><li><strong>Organização do Conhecimento</strong>: A equipe arqueológica organiza os resultados da pesquisa em documentos de conhecimento padronizados, marcando claramente a categoria de conhecimento e o resumo do conteúdo.</li><li><strong>Solicitação de Purificação</strong>: Submeter solicitação de purificação e retorno de conhecimento à Agência de Administração Planar ou ao Comitê de Leis Temporais, anexando o documento de conhecimento e o arquivo de permissão da tarefa arqueológica.</li><li><strong>Purificação de Informação</strong>: Uma equipe profissional de tecnologia de purificação de informação realiza o processo de purificação de informação de quatro etapas no documento de conhecimento.</li><li><strong>Detecção de Segurança</strong>: O conhecimento purificado passa por três detecções realizadas por uma instituição independente de detecção de segurança.</li><li><strong>Aprovação e Retorno</strong>: Após a aprovação na detecção, a instituição de aprovação assina a permissão de retorno, e o conhecimento é retornado ao banco de dados de conhecimento do próprio plano através do canal criptografado da rede de âncora.</li><li><strong>Arquivamento no Banco</strong>: O conhecimento retornado é oficialmente arquivado no banco após verificação pelo banco de conhecimento do próprio plano, e aberto a pesquisadores com permissões correspondentes.</li></ol><p>Todas as operações de retorno devem接受 &quot;auditoria de retorno&quot;. O conteúdo da auditoria inclui: se a fonte do conhecimento retornado é legal, se o processo de purificação é normativo, se a detecção de segurança é completa, se o procedimento de aprovação está em conformidade. A auditoria é de responsabilidade do Escritório de Auditoria de Retorno de Conhecimento, subordinado ao Comitê de Supervisão de Âncoras, que realiza amostragem de todas as operações de retorno do trimestre a cada trimestre e uma auditoria completa a cada ano. Os resultados da auditoria são relatados ao Conselho de Âncoras e um resumo é divulgado ao público.</p><h2 id="v-violacoes-e-responsabilidades-legais" tabindex="-1">V. Violações e Responsabilidades Legais <a class="header-anchor" href="#v-violacoes-e-responsabilidades-legais" aria-label="Permalink to &quot;V. Violações e Responsabilidades Legais&quot;">​</a></h2><p>As violações do princípio de &quot;apenas retorno de conhecimento&quot; incluem: retornar informação não purificada sem aprovação, disfarçar amostras de matéria como conhecimento para retorno, ocultar intencionalmente impressões legais do plano de origem no conhecimento retornado, e auxiliar outros a realizar retorno ilegal.</p><p>De acordo com a &quot;Constituição de Simbiose&quot; e a &quot;Lei de Gestão de Interação Interplanar&quot;, as responsabilidades legais para o retorno em violação incluem: confisco dos bens e informações retornados em violação, suspensão ou revogação da qualificação arqueológica e de travessia da parte envolvida, multa equivalente a mais de 10 vezes o valor dos bens em violação, pena de prisão em casos graves, e responsabilidade por todos os custos de reparo e indenização em caso de poluição legal ou dano ecológico.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O princípio de &quot;apenas retorno de conhecimento&quot; é a linha de base da sabedoria da civilização de simbiose de âncora no campo da interação interplanar. Com definições rigorosas, tecnologia de purificação madura, processo de retorno normativo e responsabilidades legais severas, ele constrói um robusto &quot;firewall de segurança do conhecimento&quot;. O significado deste princípio não está apenas em prevenir a poluição no nível físico, mas mais importante, em estabelecer uma visão ética do intercâmbio entre civilizações — o contato entre civilizações deve ter como núcleo o choque de ideias, não o propósito de pilhagem material.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>84-Esboço Geral do Protocolo Arqueológico</li><li>88-Diretrizes Éticas Interplanares</li><li>66-Tecnologia de Comunicação Interplanar</li></ul>',32)])])}const g=e(t,[["render",s]]);export{u as __pageData,g as default};
